local RunService = game:GetService("RunService")
local module = {}
module.__index = module

-- 创建一个新的Interval对象
-- @param func 要定期执行的函数
-- @param dt 时间间隔（秒）
-- @param inst 是否立即执行第一次
-- @return Interval对象
function module.new(func, dt, inst)
    local self = {}

    -- 设置元表，处理对象销毁后的访问
    setmetatable(self, {
        __index = function(t, k)
            local destroyed = rawget(self, "_destroyed")
            if destroyed then
                return nil
            end
            if module[k] then
                return module[k]
            end
            return rawget(self, k)
        end
    })
    
    self._func = func  -- 要执行的函数
    self._dt = dt      -- 时间间隔
    self._inst = inst  -- 是否立即执行
    self._escaped = 0  -- 已执行时间
    self._updating = nil  -- 更新连接
    self._destroyed = false  -- 是否已销毁
    self._paused = false     -- 是否暂停
    self._stopped = false    -- 是否停止

    return self
end

-- 启动间隔计时器
function module:Start()
    self:Restart()
end

-- 暂停间隔计时器
function module:Pause()
    self._paused = true
end

-- 恢复间隔计时器
function module:Resume()
    self._paused = false
end

-- 停止间隔计时器
function module:Stop()
    self:_clear()
    self._stopped = true
end

-- 重新启动间隔计时器
function module:Restart()
    self:_clear()
    self._updating = RunService.Heartbeat:Connect(function(deltaTime)
        if self._paused or self._stopped then
            return
        end
        self._escaped += deltaTime
        if self._escaped >= self._dt then
            self._escaped -= self._dt
            self._func()
        end
    end)
end

-- 销毁间隔计时器对象
function module:Destroy()
    if self._destroyed then
        return
    end
    self:_clear()
    self._destroyed = true
    table.clear(self)
end

-- 内部方法：清理计时器状态
function module:_clear()
    if self._updating then
        self._updating:Disconnect()
        self._updating = nil
    end
    -- 如果设置了立即执行，则初始时间设为间隔时间，否则为0
    self._escaped = self._inst and self._dt or 0
    self._paused = false
    self._stopped = false
end

return module